 import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, smoothstep, add, mul, sub, clamp, dot, normalize, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, DirectionalLight, Box3 } = THREE;

  const visual = config.intent?.visualSpec || {};
  const colors = visual.colors || {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#101017' }, { at: 1, hex: '#1a1a22' }]
  };
  const stops = colors.gradientStops || [];
  const stop0 = stops[0]?.hex || '#101017';
  const stop1 = stops[1]?.hex || '#1a1a22';
  const bgHex = colors.background || '#0b0b10';
  const surfaceHex = colors.surface || '#14141a';
  const paperHex = colors.paper || '#e8ecf2';
  const accentHex = colors.accent || '#ff2a38';

  const root = new Group();
  root.name = 'bento-metrics-grid';

  const materialRefs = [];
  const geometryRefs = [];
  const timelines = [];

  function killAll() {
    timelines.forEach(tl => tl?.kill && tl.kill());
    timelines.length = 0;
  }

  // --- materials -------------------------------------------------------------
  const u = uv();
  const d = dot(sub(u, vec2(0.5)), normalize(vec2(1.0, -1.0)));
  const t = clamp(add(d, 0.5).mul(1.0), 0.0, 1.0);
  const baseGrad = mix(color(stop0), color(stop1), t);
  const band = sub(smoothstep(0.35, 0.4, t), smoothstep(0.4, 0.45, t));
  const sheen = add(baseGrad, color('#ffffff').mul(mul(band, 0.06)));
  const gradNode = mix(baseGrad, sheen, 0.5);

  const cellMat = new MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.25
  });
  cellMat.colorNode = gradNode;
  cellMat.transparent = true;
  cellMat.opacity = 1;
  materialRefs.push(cellMat);

  const tickMat = new MeshStandardNodeMaterial({
    color: accentHex,
    emissive: accentHex,
    emissiveIntensity: 1.3,
    roughness: 0.4
  });
  materialRefs.push(tickMat);

  const bgU = uv();
  const bgGrad = mix(color(bgHex), color(stop0), bgU.y);
  const bgMat = new MeshBasicNodeMaterial({ colorNode: bgGrad });
  materialRefs.push(bgMat);

  // --- backdrop --------------------------------------------------------------
  const backdrop = new Mesh(new PlaneGeometry(7, 6), bgMat);
  backdrop.position.set(0, -0.25, -2.5);
  geometryRefs.push(backdrop.geometry);
  root.add(backdrop);

  // --- lighting --------------------------------------------------------------
  const key = new DirectionalLight(paperHex, 1.2);
  key.position.set(3, 6, 8);
  root.add(key);

  const rim = new DirectionalLight(accentHex, 0.8);
  rim.position.set(-4, 3, -5);
  root.add(rim);

  // --- text helpers ----------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  function getTextByRole(role, idx = 0) {
    const matches = items.filter(i => i && i.role === role);
    const v = matches[idx];
    return typeof v === 'string' ? v : (v?.text || '');
  }

  function createLabel(content, fontSize, colorStr, align, targetHeight) {
    if (!ctx.fontAtlas || !ctx.fontAtlas.createText) return null;
    const text = ctx.fontAtlas.createText(content, {
      fontSize,
      color: colorStr,
      align
    });
    const box = new Box3().setFromObject(text);
    const h = box.max.y - box.min.y;
    if (h > 0 && targetHeight) text.scale.setScalar(targetHeight / h);
    return text;
  }

  // --- cell builder ----------------------------------------------------------
  const cells = [];
  function createCell(width, height, cx, cy, valueText, labelText, valueHeight) {
    const group = new Group();
    group.position.set(cx, cy, 0);

    const shape = new Shape();
    const r = 0.04;
    const hw = width * 0.5;
    const hh = height * 0.5;
    shape.moveTo(-hw + r, hh);
    shape.lineTo(hw - r, hh);
    shape.quadraticCurveTo(hw, hh, hw, hh - r);
    shape.lineTo(hw, -hh + r);
    shape.quadraticCurveTo(hw, -hh, hw - r, -hh);
    shape.lineTo(-hw + r, -hh);
    shape.quadraticCurveTo(-hw, -hh, -hw, -hh + r);
    shape.lineTo(-hw, hh - r);
    shape.quadraticCurveTo(-hw, hh, -hw + r, hh);
    shape.closePath();

    const cellGeo = new ExtrudeGeometry(shape, {
      depth: 0.06,
      bevelEnabled: true,
      bevelThickness: 0.02,
      bevelSize: 0.03,
      bevelSegments: 4
    });
    cellGeo.center();
    geometryRefs.push(cellGeo);

    const cellMesh = new Mesh(cellGeo, cellMat);
    group.add(cellMesh);

    // tick bar
    const tickGeo = new PlaneGeometry(0.4, 0.05);
    geometryRefs.push(tickGeo);
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(-hw + 0.5 + 0.2, hh - 0.5 - 0.025, 0.065);
    group.add(tick);

    // value
    if (valueText) {
      const valueObj = createLabel(valueText, valueHeight > 0.4 ? 124 : 68, paperHex, 'left', valueHeight);
      if (valueObj) {
        valueObj.position.set(-hw + 0.5, valueHeight > 0.4 ? 0.3 : 0.25, 0.07);
        group.add(valueObj);
      }
    }

    // label
    if (labelText) {
      const labelObj = createLabel(labelText, 18, paperHex, 'left', 0.09);
      if (labelObj) {
        labelObj.position.set(-hw + 0.5, valueHeight > 0.4 ? -0.35 : -0.35, 0.07);
        group.add(labelObj);
      }
    }

    // initial entrance state
    group.position.y += 0.2;
    cellMat.opacity = 0;

    cells.push(group);
    root.add(group);
    return group;
  }

  // --- build grid ------------------------------------------------------------
  const captionText = getTextByRole('caption') || 'ATELIER METRICS / Q2 2026';
  const domValue = getTextByRole('valueLarge') || '0.002 mm';
  const domLabel = getTextByRole('label', 0) || 'Case tolerance, CNC pass';
  const sec1Value = getTextByRole('value', 0) || '38 h';
  const sec1Label = getTextByRole('label', 1) || 'Power reserve, NA-01';
  const sec2Value = getTextByRole('value', 1) || '214';
  const sec2Label = getTextByRole('label', 2) || 'Components per calibre';

  // header caption
  const caption = createLabel(captionText, 18, paperHex, 'left', 0.09);
  if (caption) {
    caption.position.set(-2.75, 2.25, 0);
    root.add(caption);
  }

  // dominant cell (left column, both rows)
  createCell(3.25, 3.5, -1.125, 0, domValue, domLabel, 0.62);

  // secondary cells (right column)
  // top right
  createCell(2.0, 1.625, 1.75, 0.9375, sec1Value, sec1Label, 0.34);
  // bottom right
  createCell(2.0, 1.625, 1.75, -0.9375, sec2Value, sec2Label, 0.34);

  // --- entrance animation ----------------------------------------------------
  const tl = gsap.timeline({ delay: 0.1 });
  timelines.push(tl);

  cells.forEach((cell, i) => {
    const finalY = cell.position.y - 0.2;
    cell.position.y = finalY;

    const targetOpacity = { value: 0 };
    tl.fromTo(
      targetOpacity,
      { value: 0 },
      {
        value: 1,
        duration: 0.5,
        ease: 'power2.out',
        onUpdate: () => {
          cellMat.opacity = targetOpacity.value;
        }
      },
      i * 0.08
    );
    tl.fromTo(
      cell.position,
      { y: finalY + 0.2 },
      { y: finalY, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
  });

  // --- interaction handlers --------------------------------------------------
  root.userData.handlers = {
    pointerenter: () => {
      gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        overwrite: true
      });
    },
    pointerleave: () => {
      const current = root.scale.x;
      const settle = gsap.timeline({ overwrite: true });
      settle.fromTo(
        root.scale,
        { x: current, y: current, z: current },
        { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' }
      );
      settle.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'power4.out'
      });
      timelines.push(settle);
    }
  };

  // --- cleanup ---------------------------------------------------------------
  root.userData.cleanup = () => {
    killAll();
    materialRefs.forEach(m => {
      m?.dispose && m.dispose();
    });
    geometryRefs.forEach(g => {
      g?.dispose && g.dispose();
    });
    root.traverse(o => {
      if (o.isLight) o.dispose?.();
    });
  };

  return root;
}
